function simulateContextDrillingVsRegistry() {
  // 1. Problem: Argument Drilling (every function must receive context)
  function legacyRepository(query, context) {
    return { query, executedBy: context.userId, traceId: context.traceId };
  }
  function legacyService(action, context) {
    return legacyRepository(`SELECT * FROM ${action}`, context);
  }
  function legacyController(req) {
    const context = { userId: req.userId, traceId: req.traceId };
    return legacyService('orders', context); // Forced to drill 'context'
  }

  // 2. Context Registry Model: Decoupling context resolution
  class RequestContextRegistry {
    constructor() {
      this.store = new Map();
    }
    set(reqId, context) {
      this.store.set(reqId, context);
    }
    get(reqId) {
      return this.store.get(reqId);
    }
    clear(reqId) {
      this.store.delete(reqId);
    }
  }

  const registry = new RequestContextRegistry();
  registry.set('req_abc_123', { userId: 'usr_99', traceId: 'tr_777888' });

  // Domain service retrieves context cleanly if correlation ID is known
  function modernService(reqId) {
    const ctx = registry.get(reqId);
    return { status: 'SUCCESS', traceId: ctx?.traceId, user: ctx?.userId };
  }

  const drilled = legacyController({ userId: 'usr_42', traceId: 'tr_111222' });
  const registered = modernService('req_abc_123');

  return { drilled, registered };
}

const result = simulateContextDrillingVsRegistry();
console.log('Drilled Context:', result.drilled.executedBy, '| Trace:', result.drilled.traceId);
console.log('Registered Context:', result.registered.user, '| Trace:', result.registered.traceId);

class PureAsyncLocalStorage {
  constructor() {
    this.currentStore = undefined;
    this.contextStack = [];
  }

  getStore() {
    return this.currentStore;
  }

  run(store, callback) {
    const previousStore = this.currentStore;
    this.currentStore = store;
    this.contextStack.push(store);

    try {
      return callback();
    } finally {
      this.contextStack.pop();
      this.currentStore = previousStore;
    }
  }
}

const als = new PureAsyncLocalStorage();

function executeDomainService(action) {
  const store = als.getStore();
  return {
    action,
    traceId: store ? store.traceId : 'NONE',
    tenant: store ? store.tenant : 'PUBLIC'
  };
}

// Simulate Concurrent Requests A and B
let resA, resB, nestedRes;

als.run({ traceId: 'trace_aaa', tenant: 'tenant_omega' }, () => {
  resA = executeDomainService('charge_card');

  // Nested Child Context
  als.run({ traceId: 'trace_aaa_child', tenant: 'tenant_omega' }, () => {
    nestedRes = executeDomainService('audit_subtask');
  });
});

als.run({ traceId: 'trace_bbb', tenant: 'tenant_alpha' }, () => {
  resB = executeDomainService('charge_card');
});

console.log('Request A Context:', resA.traceId, '| Tenant:', resA.tenant);
console.log('Nested Subtask Context:', nestedRes.traceId, '| Tenant:', nestedRes.tenant);
console.log('Request B Context:', resB.traceId, '| Tenant:', resB.tenant);
