class AsyncExecutionTracker {
  constructor() {
    this.currentId = 1; // 1 = root main execution
    this.resources = new Map();
    this.executionStack = [1];
  }

  // Hook 1: init (allocate resource and record parent trigger)
  init(type) {
    const asyncId = ++this.currentId;
    const triggerAsyncId = this.executionStack[this.executionStack.length - 1];
    this.resources.set(asyncId, { asyncId, type, triggerAsyncId, state: 'INITIALIZED' });
    return asyncId;
  }

  // Hook 2 & 3: before and after (execution context switching)
  runInContext(asyncId, callback) {
    this.executionStack.push(asyncId);
    const res = this.resources.get(asyncId);
    if (res) res.state = 'RUNNING';

    try {
      return callback();
    } finally {
      if (res) res.state = 'COMPLETED';
      this.executionStack.pop();
    }
  }

  // Trace lineage back to root
  getLineage(asyncId) {
    const chain = [];
    let curr = this.resources.get(asyncId);
    while (curr) {
      chain.push(`${curr.type}(${curr.asyncId})`);
      curr = this.resources.get(curr.triggerAsyncId);
    }
    return chain.reverse().join(' -> ');
  }
}

const tracker = new AsyncExecutionTracker();
const timerId = tracker.init('Timeout');

let lineageOutput = '';
tracker.runInContext(timerId, () => {
  const promiseId = tracker.init('Promise');
  tracker.runInContext(promiseId, () => {
    lineageOutput = tracker.getLineage(promiseId);
  });
});

console.log('Async Resource Lineage:', lineageOutput);
console.log('Root Execution Restored:', tracker.executionStack[tracker.executionStack.length - 1] === 1);

function simulateContextBoundaryContinuations() {
  class MockAsyncContext {
    constructor() {
      this.activeStore = undefined;
    }
    run(store, fn) {
      const prev = this.activeStore;
      this.activeStore = store;
      try {
        return fn();
      } finally {
        this.activeStore = prev;
      }
    }
    getStore() {
      return this.activeStore;
    }
    // Bind captures the store at wrap time and restores it on execution
    bind(fn) {
      const capturedStore = this.activeStore;
      return (...args) => {
        const prev = this.activeStore;
        this.activeStore = capturedStore;
        try {
          return fn(...args);
        } finally {
          this.activeStore = prev;
        }
      };
    }
  }

  const ctx = new MockAsyncContext();
  let brokenResult = null;
  let boundResult = null;

  // Simulate an external unmanaged event queue
  const eventQueue = [];
  function scheduleExternalEvent(cb) {
    eventQueue.push(cb);
  }

  ctx.run({ reqId: 'req_99', tenant: 'FINANCE' }, () => {
    // 1. Unbound callback: loses context when executed outside run()
    scheduleExternalEvent(() => {
      brokenResult = ctx.getStore()?.reqId ?? 'LOST_CONTEXT';
    });

    // 2. Bound callback: preserves captured context
    const safeCallback = ctx.bind(() => {
      boundResult = ctx.getStore()?.reqId ?? 'LOST_CONTEXT';
    });
    scheduleExternalEvent(safeCallback);
  });

  // Drain external event queue outside the active context scope
  while (eventQueue.length > 0) {
    const task = eventQueue.shift();
    task();
  }

  return { brokenResult, boundResult };
}

const audit = simulateContextBoundaryContinuations();
console.log('Unbound Continuation Result:', audit.brokenResult, '(Hazard!)');
console.log('Bound Continuation Result:', audit.boundResult, '(Preserved Successfully)');

function parseAndPropagateW3CTraceContext(incomingHeader, localSpanId = '1122334455667788') {
  // W3C format: version-trace_id-parent_id-trace_flags (e.g. 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01)
  const regex = /^([0-9a-f]{2})-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/i;
  const match = incomingHeader.match(regex);

  if (!match) {
    throw new Error(`Invalid W3C traceparent header: ${incomingHeader}`);
  }

  const [_, version, traceId, parentSpanId, traceFlags] = match;

  // Active context inside this microservice
  const currentContext = {
    version,
    traceId,
    parentSpanId,
    currentSpanId: localSpanId,
    traceFlags,
    isSampled: (parseInt(traceFlags, 16) & 1) === 1
  };

  // Format outgoing traceparent for downstream services (pointing parentId to currentSpanId)
  const outgoingTraceParent = `${version}-${traceId}-${localSpanId}-${traceFlags}`;

  return {
    currentContext,
    outgoingTraceParent
  };
}

const rawHeader = '00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01';
const traceSession = parseAndPropagateW3CTraceContext(rawHeader, 'a1b2c3d4e5f60718');

console.log('Incoming Trace ID:', traceSession.currentContext.traceId);
console.log('Parent Span ID:', traceSession.currentContext.parentSpanId);
console.log('Local Span ID:', traceSession.currentContext.currentSpanId, '| Sampled:', traceSession.currentContext.isSampled);
console.log('Outgoing Header for Downstream:', traceSession.outgoingTraceParent);
